{
  "scenario_id": "sc-f69eea",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2015, 2024],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.08/yr; A/E rises from ~0.63-0.70 in 2015-2018 to ~1.26-1.31 in 2023-2024 (2015-18 mean ~0.66, 2021-24 mean ~1.19)",
      "confidence": 0.85,
      "evidence": [
        "artifacts/ae_death_by_year.csv: AE values 0.626, 0.701, 0.637, 0.660, 0.784, 0.983, 1.063, 1.113, 1.261, 1.307 for 2015-2024",
        "summary.json: Death overall_ae 1.004 over 5,020 claims masks the persistent level shift from below to above baseline",
        "Empirical year-to-year AE spread (~0.26 SD) is far above Poisson 1/sqrt(E) (~0.03-0.07), so the finding is based on sustained level/trend rather than single-year Poisson z-scores"
      ],
      "recommended_action": "Investigate Death claim development, data quality, age/gender/cause-of-death drivers, and the expected mortality basis; assess whether early low A/E reflects model overstatement and recent high A/E reflects adverse mortality, then update pricing/valuation assumptions if confirmed. CI, TPD, and IP annual A/E and IP termination remain broadly around 1.0 and appear clean; no action on those lines."
    }
  ]
}

